function finishConfirm(value){if(!$('confirmDialog').open)return;$('confirmDialog').close();const done=confirmResolver;confirmResolver=null;if(done)done(value)}
$('confirmAccept').addEventListener('click',()=>finishConfirm(true));$('confirmCancel').addEventListener('click',()=>finishConfirm(false));$('confirmClose').addEventListener('click',()=>finishConfirm(false));$('confirmDialog').addEventListener('cancel',e=>{e.preventDefault();finishConfirm(false)});
