$('addCalendarCode')?.addEventListener('click',()=>{if(!selectedArchiveDate){status('Tap a calendar date first, then choose Add roster / availability.');return}const raw=calendarCodes[selectedArchiveDate]||[];const existing=Array.isArray(raw)?raw:(raw?[raw]:[]);document.querySelectorAll('input[name="calendarCodeType"]').forEach(x=>x.checked=existing.includes(x.value));$('calendarDateMode').value='range';$('calendarCodeStart').value=selectedArchiveDate;$('calendarCodeEnd').value=selectedArchiveDate;$('calendarIndividualDates').innerHTML=`<label>Date 1<input type="date" class="calendar-individual-date" value="${selectedArchiveDate}"></label>`;$('calendarRangeFields').hidden=false;$('calendarMultipleFields').hidden=true;$('calendarCodeDialog').showModal()});
$('calendarDateMode')?.addEventListener('change',e=>{const multi=e.target.value==='multiple';$('calendarRangeFields').hidden=multi;$('calendarMultipleFields').hidden=!multi});
$('calendarAddDate')?.addEventListener('click',()=>{const wrap=$('calendarIndividualDates'),n=wrap.querySelectorAll('.calendar-individual-date').length+1,label=document.createElement('label');label.textContent=`Date ${n}`;const input=document.createElement('input');input.type='date';input.className='calendar-individual-date';label.appendChild(input);wrap.appendChild(label)});
$('calendarCodeSave')?.addEventListener('click',()=>{const codes=[...document.querySelectorAll('input[name="calendarCodeType"]:checked')].map(x=>x.value);if(!codes.length){status('Tick at least one leave or unavailability type.');return}let dates=[];if($('calendarDateMode').value==='range'){const start=$('calendarCodeStart').value,end=$('calendarCodeEnd').value;if(!start||!end){status('Select both a start and end date.');return}if(end<start){status('The end date must be on or after the start date.');return}const cur=new Date(start+'T12:00:00'),last=new Date(end+'T12:00:00');while(cur<=last){dates.push([cur.getFullYear(),String(cur.getMonth()+1).padStart(2,'0'),String(cur.getDate()).padStart(2,'0')].join('-'));cur.setDate(cur.getDate()+1)}}else{dates=[...new Set([...document.querySelectorAll('.calendar-individual-date')].map(x=>x.value).filter(Boolean))];if(!dates.length){status('Add at least one valid date.');return}}dates.forEach(key=>{const old=calendarCodes[key]||[],list=Array.isArray(old)?old:(old?[old]:[]);calendarCodes[key]=[...new Set([...list,...codes])]});localStorage.setItem(CALENDAR_CODES_KEY,JSON.stringify(calendarCodes));$('calendarCodeDialog').close();renderArchiveCalendar();status(`${codes.join(', ')} added to ${dates.length} ${dates.length===1?'date':'dates'}.`)});
