function updateDefectUnitField(){
 const wrap=$('defectUnitWrap');if(!wrap)return;
 const selected=$('relatedTrain')?.value||'';
 const index=selected?state.trains.findIndex((tr,i)=>(tr.id||String(i))===selected):-1;
 const train=index>=0?state.trains[index]:null;
 if(train&&train.unit&&train.unit2){
  wrap.innerHTML=`<label>Unit number<select id="defectUnitNumber" required><option value="">Which unit is affected?</option><option value="${esc(train.unit)}">First unit — ${esc(train.unit)}</option><option value="${esc(train.unit2)}">Second unit — ${esc(train.unit2)}</option></select></label><small class="muted">This train is a double set. Select the affected unit.</small>`;
 }else if(train&&train.unit){
  wrap.innerHTML=`<label>Unit number<input id="defectUnitNumber" value="${esc(train.unit)}" readonly></label><small class="muted">Single set — unit number filled from the train details.</small>`;
 }else{
  wrap.innerHTML=`<label>Unit number (optional)<input id="defectUnitNumber" type="text" maxlength="6" placeholder="Six digit unit number or N/A" autocomplete="off"></label>`;
  $('defectUnitNumber')?.addEventListener('input',e=>{e.target.value=/^N?\/?A?$/i.test(e.target.value.trim())&&e.target.value.trim()?'N/A':e.target.value.replace(/\D/g,'').slice(0,6)});
 }
 // Attach after the defect unit field has been dynamically inserted.
 ;
}
function openTicketCustomDialog(target){ticketCustomTarget=target;const operator=target==='operator';$('ticketCustomTitle').textContent=operator?'Other train operating company (TOC)':'Other reason';$('ticketCustomLabel').textContent=operator?'Enter the TOC name':'Enter delay / incident reason';$('ticketCustomValue').value=operator?ticketCustomOperator:ticketCustomReason;$('ticketCustomDialog').showModal();$('ticketCustomValue').focus()}
$('ticketCustomCancel').addEventListener('click',()=>{$('ticketCustomDialog').close();if(ticketCustomTarget==='operator'){if($('ticketOperatorOther'))$('ticketOperatorOther').checked=false}else{const select=$('ticketReason');if(select)select.value=''}ticketCustomTarget=''});$('ticketCustomClose').addEventListener('click',()=>$('ticketCustomCancel').click());$('ticketCustomForm').addEventListener('submit',e=>{e.preventDefault();const value=$('ticketCustomValue').value.trim();if(!value){$('ticketCustomValue').focus();return}if(ticketCustomTarget==='operator'){ticketCustomOperator=value;$('ticketOperatorCustom').textContent='Other TOC: '+value}else{ticketCustomReason=value;$('ticketReasonCustom').textContent='Custom reason: '+value}$('ticketCustomDialog').close();ticketCustomTarget=''});
