function populateShiftHeadcodeSelect(selectId){const select=$(selectId);if(!select)return;const options=(state.trains||[]).map((train,index)=>({train,index})).filter(({train})=>/^[0-9][A-Z][0-9]{2}$/i.test(String(train.headcode||'').trim()));select.innerHTML='<option value="">Select a train / headcode…</option>'+options.map(({train,index})=>`<option value="${esc(train.id||String(index))}">${esc(String(train.headcode).trim().toUpperCase())} · ${esc(train.from||'Working')}</option>`).join('');select.disabled=options.length===0;if(!options.length)select.innerHTML='<option value="">No headcoded trains recorded for this shift</option>';}
function updateLogPhotoUnits(){const trainId=$('logPhotoTrain').value,train=state.trains.find((tr,i)=>(tr.id||String(i))===trainId),units=[train?.unit,train?.unit2].filter(Boolean).map(String);$('logPhotoUnit').innerHTML='<option value="">No unit selected</option>'+[...new Set(units)].map(u=>`<option value="${esc(u)}">${esc(u)}</option>`).join('');$('logPhotoUnit').disabled=!units.length;}
